23	/**
24	* Scales a single-precision complex floating-point number by a real-valued single-precision floating-point scalar constant.
25	*
26	* @param alpha   scalar constant
27	* @param z       input value
28	* @return        result
29	*
30	* @example
31	* #include "stdlib/complex/float32/ctor.h"
32	* #include "stdlib/complex/float32/real.h"
33	* #include "stdlib/complex/float32/imag.h"
34	*
35	* stdlib_complex64_t z = stdlib_complex64( 5.0f, 3.0f );
36	*
37	* stdlib_complex64_t out = stdlib_base_complex64_scale( 5.0f, z );
38	*
39	* float re = stdlib_complex64_real( out );
40	* // returns 25.0f
41	*
42	* float im = stdlib_complex64_imag( out );
43	* // returns 15.0f
44	*/
45	stdlib_complex64_t stdlib_base_complex64_scale( const float alpha, const stdlib_complex64_t z ) {
46		float re;
47		float im;
48	
49		stdlib_complex64_reim( z, &re, &im );
50		return stdlib_complex64( re * alpha, im * alpha );
51	}
